const $=s=>document.querySelector(s);const tokenKey='lac_admin_token';
const statuses=['new','confirmed','processing','shipped','delivered','completed','cancelled','refunded'];
const fmt=n=>`KSh ${Number(n||0).toLocaleString()}`;
function token(){return sessionStorage.getItem(tokenKey)||''}
function showDashboard(){ $('#login').classList.add('hidden'); $('#dashboard').classList.remove('hidden'); loadOrders(); }
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token()}`,...(opts.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');return d}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginMsg').textContent='Signing in…';try{const r=await fetch('/.netlify/functions/admin-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#password').value})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to sign in');sessionStorage.setItem(tokenKey,d.access_token);showDashboard()}catch(err){$('#loginMsg').textContent=err.message}};
$('#logout').onclick=()=>{sessionStorage.removeItem(tokenKey);location.reload()};
async function loadOrders(){try{const {orders=[]}=await api('/.netlify/functions/admin-orders');const paid=orders.filter(x=>x.payment_status==='paid');const pending=orders.filter(x=>!['paid','refunded'].includes(x.payment_status));const revenue=paid.reduce((a,x)=>a+Number(x.total_amount||0),0);$('#totalOrders').textContent=orders.length;$('#paidOrders').textContent=paid.length;$('#pendingOrders').textContent=pending.length;$('#revenue').textContent=fmt(revenue);$('#orders').innerHTML=orders.map(o=>`<tr><td><strong>${o.order_number}</strong></td><td>${o.customer_name}<br><small>${o.customer_phone}</small></td><td>${fmt(o.total_amount)}</td><td>${o.payment_status}</td><td>${o.order_status}</td><td>${new Date(o.created_at).toLocaleString()}</td><td><select data-id="${o.id}" class="status"><option value="">Update…</option>${statuses.map(s=>`<option value="${s}">${s}</option>`).join('')}</select></td></tr>`).join('');document.querySelectorAll('.status').forEach(s=>s.onchange=async()=>{if(!s.value)return;try{await api(`/.netlify/functions/admin-update-order?id=${encodeURIComponent(s.dataset.id)}`,{method:'PATCH',body:JSON.stringify({order_status:s.value})});loadOrders()}catch(err){alert(err.message)}})}catch(err){if(/Unauthorized|Admin access/.test(err.message)){sessionStorage.removeItem(tokenKey);location.reload()}else alert(err.message)}}
if(token())showDashboard();
